  JSONObject removedDestination=fixture();CategoryEdits.Plan destinationPlan=CategoryEdits.plan(removedDestination,"a",false);Ledger.find(removedDestination.getJSONArray("categories"),"expense-7").put("deleted",true).put("archived",true);String untouched=removedDestination.toString();rejects(()->CategoryEdits.edit(removedDestination,destinationPlan,"expense-7"),"A logically deleted destination must be refused");rejects(()->CategoryEdits.create(removedDestination,destinationPlan,"Suscripciones"),"Creation must not reactivate a logically deleted category");yes(removedDestination.toString().equals(untouched),"Refusing a deleted name must not even unarchive the category");
