  JSONObject status=fixture();CategoryEdits.Plan statusPlan=CategoryEdits.plan(status,"a",true);Ledger.find(status.getJSONArray("transactions"),"c").put("status","deleted");String statusBefore=status.toString();rejects(()->CategoryEdits.edit(status,statusPlan,"expense-0"),"A removed status must invalidate an open sheet");yes(status.toString().equals(statusBefore),"A removed status must preserve every category in the batch");
